def esc(x):return html.escape(str(x),quote=True)
def inline(s):
 s=esc(s)
 s=re.sub(r'\[([^\]]+)\]\((https?://[^\s)]+|/[^\s)]+)\)',lambda m:f'<a href="{m[2]}">{m[1]}</a>',s)
 s=re.sub(r'\*\*(.+?)\*\*',r'<strong>\1</strong>',s)
 s=re.sub(r'`([^`]+)`',r'<code>\1</code>',s)
 return s
def md(text):
 lines=text.splitlines();out=[];i=0
 while i<len(lines):
  l=lines[i];i+=1
  if not l.strip():continue
  if l.startswith('<div class="page-break"'):out.append('<hr class="chapter-break">');continue
  if l.startswith('```'):
   code=[]
   while i<len(lines) and not lines[i].startswith('```'):code.append(lines[i]);i+=1
   i+=1;out.append('<pre><code>'+esc('\n'.join(code))+'</code></pre>');continue
  if l.startswith('|'):
   rows=[l]
   while i<len(lines) and lines[i].startswith('|'):rows.append(lines[i]);i+=1
   cells=[[c.strip() for c in row.strip().strip('|').split('|')] for row in rows]
   cells=[c for c in cells if not all(re.fullmatch(r'[-: ]+',x) for x in c)]
   out.append('<div class="table-wrap" tabindex="0" role="region" aria-label="Data table"><table><thead><tr>'+''.join('<th scope="col">'+inline(c)+'</th>' for c in cells[0])+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+inline(c)+'</td>' for c in row)+'</tr>' for row in cells[1:])+'</tbody></table></div>');continue
  m=re.match(r'^(#{1,4}) (.+)',l)
  if m:
   n=len(m[1]);title=m[2];ch=re.match(r'第(\d+)章',title);ident=f' id="chapter-{ch[1]}"' if ch else ''
   out.append(f'<h{n}{ident}>{inline(title)}</h{n}>');continue
  if l.startswith('- '):
   items=[l[2:]]
   while i<len(lines) and lines[i].startswith('- '):items.append(lines[i][2:]);i+=1
   out.append('<ul>'+''.join('<li>'+inline(x)+'</li>' for x in items)+'</ul>');continue
  out.append('<p>'+inline(l)+'</p>')
 return '\n'.join(out)
